-- ============================================================
-- Leo Learning — footer copyright and "Powered by" credit (migration 032)
-- Editable from the owner panel's Settings tab. {year} and {name} in the
-- copyright are filled in when the footer renders.
--   mysql -u root e-learning < database/migrations/032_footer_settings.sql
-- ============================================================

USE `e-learning`;

INSERT INTO site_settings (skey, svalue) VALUES
  ('footerCopyright', '© {year} {name}. All rights reserved.'),
  ('footerCopyrightBn', '© {year} {name}। সর্বস্বত্ব সংরক্ষিত।'),
  ('poweredByText', 'Powered by'),
  ('poweredByTextBn', 'পাওয়ার্ড বাই'),
  ('poweredByUrl', 'https://www.leotechbd.com'),
  ('poweredByLogo', 'data:image/png;base64,')
ON DUPLICATE KEY UPDATE svalue = svalue;
